sys_script_include.script:
var TrainingHubUtils = Class.create();
TrainingHubUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	// Checks if a schedule already exists for the same course and date (STRY 3)
	checkDuplicateDate: function() {
        var courseId = this.getParameter('sysparm_course');
        var selectedDate = this.getParameter('sysparm_date'); 
        var scheduleId = this.getParameter('sysparm_id');

        // Querying all schedules for the selected course. 
        var gr = new GlideRecord('x_1960572_training_schedule');
        gr.addQuery('course', courseId);        
        gr.query();

        while (gr.next()) {
            // Ignore the current record if we are updating an existing schedule
            if (scheduleId && gr.getUniqueValue() == scheduleId) {
                continue;
            }
            // Compare the inputted date with both display value and internal value of saved records
            if (gr.getDisplayValue('date') == selectedDate || gr.getValue('date') == selectedDate) {
                return "true"; // Duplicate found
            }
        }
        return "false"; // No duplicate found, safe to proceed
    },

    // Returns only active users with the instructor role for the schedule form
    refQualInstructor: function() {
        var instructorsToShow = [];
        var grUserRole = new GlideRecord("sys_user_has_role");
        grUserRole.addQuery("role.name", "x_1960572_training.instructor");
        grUserRole.addQuery("user.active", true);
        grUserRole.query();

        while (grUserRole.next()) {
            instructorsToShow.push(grUserRole.getValue("user"));
        }

        // No valid instructors found 
        if (instructorsToShow.length == 0) {
            return "sys_id=NULL";
        }

        return "sys_idIN" + instructorsToShow.join(",");
    },

    // Reference Qualifier for Schedules
    refQualSchedule: function(courseId) {
        if (!courseId) {
            return "sys_id=NULL";
        }

        var schedulesToShow = [];

        var grSchedule = new GlideRecord("x_1960572_training_schedule");
        grSchedule.addQuery("course", courseId);

        // Calculate tomorrow to enforce the 1-day enrollment deadline
        var tomorrow = new GlideDateTime();
		tomorrow.addDaysLocalTime(1);
		// Filters out past dates and schedules within 1 day (STRY 11)
        grSchedule.addQuery("date", ">", tomorrow.getValue());

		// Skip schedules where user is the instructor (STRY 10)
		grSchedule.addQuery("instructor", "!=", gs.getUserID());

        grSchedule.query();

        while (grSchedule.next()) {
            var occupied = parseInt(grSchedule.getValue("occupied_seats") || 0);
            var max = parseInt(grSchedule.getValue("max_seats") || 0);

            // Only include schedules that still have open slots (STRY 9)
            if (occupied < max) {
                schedulesToShow.push(grSchedule.getUniqueValue());
            }
        }

        if (schedulesToShow.length == 0) {
            return "sys_id=NULL";
        }

        return "sys_idIN" + schedulesToShow.join(",");
    },


    type: 'TrainingHubUtils'
});
